import{_ as a,o as l,c as o,a2 as r}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"প্রযুক্তি উন্মুক্তকরণ এবং ভাগাভাগির প্রক্রিয়া","description":"","frontmatter":{},"headers":[],"relativePath":"bn/69-技术开放与共享机制.md","filePath":"bn/69-技术开放与共享机制.md","lastUpdated":null}'),d={name:"bn/69-技术开放与共享机制.md"};function e(i,t,n,h,u,s){return l(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="প্রযুক্তি-উন্মুক্তকরণ-এবং-ভাগাভাগির-প্রক্রিয়া" tabindex="-1">প্রযুক্তি উন্মুক্তকরণ এবং ভাগাভাগির প্রক্রিয়া <a class="header-anchor" href="#প্রযুক্তি-উন্মুক্তকরণ-এবং-ভাগাভাগির-প্রক্রিয়া" aria-label="Permalink to &quot;প্রযুক্তি উন্মুক্তকরণ এবং ভাগাভাগির প্রক্রিয়া&quot;">​</a></h1><table tabindex="0"><thead><tr><th>আইটেম</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>69</td></tr><tr><td>মডিউল</td><td>প্রযুক্তি ও শক্তি ব্যবস্থা</td></tr><tr><td>মূল কীওয়ার্ড</td><td>প্রযুক্তি উন্মুক্তকরণ, জ্ঞান ভাগাভাগি, ওপেন সোর্স নিয়ম, প্রযুক্তি বিস্তার, একচেটিয়া বিরোধী</td></tr></tbody></table><h2 id="১-প্রযুক্তি-উন্মুক্তকরণের-মূল-ধারণা" tabindex="-1">১. প্রযুক্তি উন্মুক্তকরণের মূল ধারণা <a class="header-anchor" href="#১-প্রযুক্তি-উন্মুক্তকরণের-মূল-ধারণা" aria-label="Permalink to &quot;১. প্রযুক্তি উন্মুক্তকরণের মূল ধারণা&quot;">​</a></h2><p>অ্যাঙ্কর সিম্বায়োসিস সভ্যতার প্রযুক্তি উন্মুক্তকরণ এবং ভাগাভাগির প্রক্রিয়া হল প্রযুক্তির ক্ষেত্রে &quot;বেশি কাজ বেশি পাও, নিজে থেকে বেড়ে ওঠা, সবার পথ আছে, সব জাতি একসাথে অগ্রগতি&quot; মূল নীতির প্রকৃত প্রকাশ। এর মূল ধারণা হল: প্রযুক্তিগত জ্ঞান সমগ্র সভ্যতার সমষ্টিগত বিবর্তনের প্রডাক্ট হিসেবে, সমগ্র সভ্যতার জন্য ভাগাভাগি করা উচিত; প্রযুক্তি একচেটিয়া এবং জ্ঞানের বাধা হল প্রযুক্তির ক্ষেত্রে লুটের ব্যবস্থার অবশিষ্টাংশ, অবশ্যই প্রণালীগত নকশার মাধ্যমে দূর করতে হবে।</p><p>প্রযুক্তি উন্মুক্তকরণের মানে প্রযুক্তি গবেষণাকারীদের অবদানকে অস্বীকার করা নয়। বরং, সিম্বায়োসিস সভ্যতা &quot;অবদান পরিমাপযোগ্য, লাভ ট্রেসযোগ্য&quot; প্রযুক্তি উদ্দীপনা প্রক্রিয়া প্রতিষ্ঠা করেছে, যা নিশ্চিত করে যে গবেষণাকারীদের শ্রম যুক্তিসঙ্গত প্রতিদান পায়, একই সাথে প্রযুক্তিগত ফলাফল সর্বনিম্ন প্রবেশদ্বারে সকল প্রাণীর কল্যাণে পৌঁছাতে পারে। এই প্রক্রিয়ার সারাংশ হল প্রযুক্তিকে &quot;কয়েকজনের একচেটিয়া পণ্য&quot; থেকে &quot;সমগ্র সভ্যতার ভাগাভাগির মৌলিক অবকাঠামো&quot;তে রূপান্তর করা।</p><h2 id="২-প্রযুক্তি-শ্রেণীবিভাগ-উন্মুক্তকরণ-ব্যবস্থা" tabindex="-1">২. প্রযুক্তি শ্রেণীবিভাগ উন্মুক্তকরণ ব্যবস্থা <a class="header-anchor" href="#২-প্রযুক্তি-শ্রেণীবিভাগ-উন্মুক্তকরণ-ব্যবস্থা" aria-label="Permalink to &quot;২. প্রযুক্তি শ্রেণীবিভাগ উন্মুক্তকরণ ব্যবস্থা&quot;">​</a></h2><p>প্রযুক্তি উন্মুক্তকরণ ঝুঁকির স্তর এবং পরিপক্কতা অনুযায়ী শ্রেণীবিভাগ উন্মুক্তকরণ প্রয়োগ করে:</p><table tabindex="0"><thead><tr><th>উন্মুক্তকরণের স্তর</th><th>প্রযোজ্য প্রযুক্তি</th><th>উন্মুক্তকরণের পদ্ধতি</th><th>প্রবেশের শর্ত</th></tr></thead><tbody><tr><td>সম্পূর্ণ উন্মুক্ত</td><td>R0, R1 স্তরের পরিপক্ক প্রযুক্তি</td><td>সমস্ত প্রযুক্তিগত নথি এবং নকশা ড্রয়িং বিনামূল্যে প্রকাশ</td><td>কোনো প্রবেশদ্বার নেই, সব জীবন পেতে পারে</td></tr><tr><td>অনুমতি উন্মুক্ত</td><td>R2 স্তরের পরিপক্ক প্রযুক্তি</td><td>মূল নীতি প্রকাশ, প্রকৌশল বাস্তবায়নের জন্য অনুমতি আবেদন করতে হবে</td><td>ভিত্তিগত নিরাপত্তা প্রশিক্ষণ পাস করতে হবে, ব্যবহারের নিয়ম মেনে চলার প্রতিশ্রুতি</td></tr><tr><td>সীমাবদ্ধ উন্মুক্ত</td><td>R3 স্তরের প্রযুক্তি</td><td>শুধুমাত্র অনুমোদিত গবেষণা প্রতিষ্ঠানের জন্য উন্মুক্ত, নিরাপত্তা চুক্তি স্বাক্ষর করতে হবে</td><td>S-স্তরের বিচ্ছিন্ন স্থান এবং নৈতিক পর্যালোচনার যোগ্যতা থাকতে হবে</td></tr><tr><td>উন্মুক্ত নিষিদ্ধ</td><td>R4 স্তরের নিষিদ্ধ প্রযুক্তি</td><td>উন্মুক্ত নয়</td><td>সম্পূর্ণরূপে নিষিদ্ধ</td></tr></tbody></table><p>সম্পূর্ণ উন্মুক্ত প্রযুক্তির জন্য, সিম্বায়োসিস সভ্যতা &quot;ওপেন সোর্স নিয়ম লাইব্রেরি&quot; প্রতিষ্ঠা করেছে — বাস্তব বিশ্বের ওপেন সোর্স সফটওয়্যার কমিউনিটির মতো একটি প্রযুক্তিগত জ্ঞান ভাণ্ডার। সমস্ত গবেষণাকারী তাদের প্রযুক্তিগত ফলাফল ওপেন সোর্স নিয়ম লাইব্রেরিতে জমা দিতে পারে, প্রযুক্তি কমিটির পর্যালোচনার পর সমগ্র সভ্যতার জন্য উন্মুক্ত করা হয়। ওপেন সোর্স নিয়ম লাইব্রেরির প্রযুক্তিগুলি &quot;সিম্বায়োসিস শেয়ারিং লাইসেন্স&quot; গ্রহণ করে, যা স্বাধীন ব্যবহার, সংশোধন এবং পুনর্বিতরণের অনুমতি দেয়, কিন্তু ডেরিভেটিভ কাজগুলিকেও একইভাবে ওপেন সোর্স হিসেবে শেয়ার করতে হবে।</p><h2 id="৩-প্রযুক্তি-বিস্তারের-মৌলিক-অবকাঠামো" tabindex="-1">৩. প্রযুক্তি বিস্তারের মৌলিক অবকাঠামো <a class="header-anchor" href="#৩-প্রযুক্তি-বিস্তারের-মৌলিক-অবকাঠামো" aria-label="Permalink to &quot;৩. প্রযুক্তি বিস্তারের মৌলিক অবকাঠামো&quot;">​</a></h2><p>প্রযুক্তি উন্মুক্তকরণ ফর্মালতায় পরিণত না হওয়া নিশ্চিত করতে, সিম্বায়োসিস সভ্যতা নিখুঁত প্রযুক্তি বিস্তারের মৌলিক অবকাঠামো তৈরি করেছে:</p><ol><li><strong>প্রযুক্তি শিক্ষা ব্যবস্থা</strong>: সিম্বায়োসিস শিক্ষা ব্যবস্থায় ভিত্তিগত নিয়ম প্রকৌশল জ্ঞানকে সাধারণ শিক্ষার বিষয় হিসেবে তালিকাভুক্ত করা হয়েছে, নিশ্চিত করে যে প্রতিটি জীবনের ভিত্তিগত প্রযুক্তি বোঝা এবং প্রয়োগ করার ক্ষমতা আছে। উন্নত প্রযুক্তি শিক্ষা সব ইচ্ছুক শিক্ষার্থীর জন্য বিনামূল্যে উন্মুক্ত</li><li><strong>প্রযুক্তি প্রচার নেটওয়ার্ক</strong>: বিমান-আন্তঃ যোগাযোগ নেটওয়ার্কের উপর নির্ভর করে, সমগ্র মহাজাগতিক প্রযুক্তি প্রচার প্ল্যাটফর্ম তৈরি করা হয়েছে, যার মধ্যে রয়েছে অনলাইন কোর্স, প্রযুক্তি ফোরাম, ভার্চুয়াল ল্যাবরেটরি ইত্যাদি, যা দূরবর্তী বিমানের শিক্ষার্থীদেরও সর্বশেষ প্রযুক্তিগত জ্ঞান পেতে সক্ষম করে</li><li><strong>পাবলিক প্রযুক্তি সুবিধা</strong>: কমিউনিটি অ্যাঙ্করে পাবলিক প্রযুক্তি ল্যাবরেটরি এবং উত্পাদন সরঞ্জাম সজ্জিত করা হয়েছে, যেকোনো জীবন অগ্রিম বুকিং করে ব্যবহার করতে পারে, প্রযুক্তিগত জ্ঞানকে বাস্তব প্রডাক্টে রূপান্তর করতে পারে</li><li><strong>প্রযুক্তি গুরু পদ্ধতি</strong>: উন্নত প্রযুক্তি বিশেষজ্ঞদের নিয়মিত প্রযুক্তি গুরু হিসেবে কাজ করার বাধ্যবাধকতা আছে, প্রাথমিক শিক্ষার্থীদের নির্দেশনা দেওয়া, এই বাধ্যবাধকতা তাদের সিম্বায়োসিস অবদানের ডিগ্রিতে গণনা করা হয়</li></ol><h2 id="৪-প্রযুক্তি-অবদানের-পরিমাপ-এবং-উদ্দীপনা" tabindex="-1">৪. প্রযুক্তি অবদানের পরিমাপ এবং উদ্দীপনা <a class="header-anchor" href="#৪-প্রযুক্তি-অবদানের-পরিমাপ-এবং-উদ্দীপনা" aria-label="Permalink to &quot;৪. প্রযুক্তি অবদানের পরিমাপ এবং উদ্দীপনা&quot;">​</a></h2><p>প্রযুক্তি উন্মুক্তকরণ প্রক্রিয়ার টেকসইতা যুক্তিসঙ্গত অবদান পরিমাপ এবং উদ্দীপনা ব্যবস্থার উপর নির্ভর করে:</p><ul><li><strong>অবদানের ডিগ্রি পরিমাপ</strong>: গবেষণাকারীদের জমা দেওয়া প্রযুক্তিগত ফলাফল ওপেন সোর্স নিয়ম লাইব্রেরিতে সংগ্রহীত হওয়ার পর, তার প্রযুক্তিগত মূল্য, প্রয়োগের পরিসর এবং ডেরিভেটিভ অবদান অনুযায়ী &quot;প্রযুক্তি অবদানের ডিগ্রি&quot; গণনা করা হয়। অবদানের ডিগ্রি হল যৌথ উৎপাদন ঠিকাদার প্রক্রিয়ায় সম্পদ বণ্টনের গুরুত্বপূর্ণ ভিত্তি</li><li><strong>অগ্রাধিকার ব্যবহারের অধিকার</strong>: প্রযুক্তি গবেষণাকারী নির্দিষ্ট সময়ের মধ্যে তার প্রযুক্তিগত ফলাফলের অগ্রাধিকার ব্যবহারের অধিকার এবং উন্নত সেবার অগ্রাধিকার উপভোগ করে, কিন্তু প্রযুক্তির প্রচারের অধিকার একচেটিয়া করতে পারবে না</li><li><strong>সম্মান ব্যবস্থা</strong>: সমগ্র সভ্যতার জন্য গুরুত্বপূর্ণ অবদান রাখা প্রযুক্তি গবেষণাকারীদের &quot;সিম্বায়োসিস প্রযুক্তি পদক&quot; ইত্যাদি সম্মান প্রদান করা হয়, তাদের কৃতিত্ব সভ্যতার প্রযুক্তি ইতিহাসে লিপিবদ্ধ করা হয়</li><li><strong>ক্রমাগত লাভ</strong>: প্রচুর শক্তি খরচ করা উন্নত প্রযুক্তি প্রয়োগের জন্য, গবেষণাকারী প্রয়োগের লাভ থেকে যুক্তিসঙ্গত অনুপাতের ভাগাভাগি পেতে পারে, কিন্তু ভাগাভাগির অনুপাত একচেটিয়া বিরোধী আইনের সর্বোচ্চ সীমা দ্বারা সীমাবদ্ধ</li></ul><h2 id="৫-একচেটিয়া-বিরোধী-এবং-প্রযুক্তি-ন্যায়বিচার" tabindex="-1">৫. একচেটিয়া বিরোধী এবং প্রযুক্তি ন্যায়বিচার <a class="header-anchor" href="#৫-একচেটিয়া-বিরোধী-এবং-প্রযুক্তি-ন্যায়বিচার" aria-label="Permalink to &quot;৫. একচেটিয়া বিরোধী এবং প্রযুক্তি ন্যায়বিচার&quot;">​</a></h2><p>প্রযুক্তি উন্মুক্তকরণ প্রক্রিয়ার কার্যকরীকরণ একচেটিয়া বিরোধী আইন দ্বারা কঠোরভাবে নিশ্চিত করা হয়:</p><ul><li>কোনো প্রতিষ্ঠান বা ব্যক্তিকে পেটেন্ট বাধা, প্রযুক্তি গোপনীয়তা ইত্যাদি মাধ্যমে ভিত্তিগত প্রযুক্তির প্রচারের অধিকার একচেটিয়া করা নিষিদ্ধ</li><li>&quot;প্রযুক্তি লক&quot; আচরণ নিষিদ্ধ, অর্থাৎ ইচ্ছাকৃতভাবে অসামঞ্জস্যপূর্ণ মানদণ্ড তৈরি করে ব্যবহারকারীদের নির্দিষ্ট প্রযুক্তি সরবরাহকারীর উপর নির্ভরশীল হতে বাধ্য করা</li><li>মূল মৌলিক অবকাঠামো শ্রেণীর প্রযুক্তি (যেমন অ্যাঙ্কর হার্ডওয়্যার, শক্তি বণ্টন, বিমান-আন্তঃ যোগাযোগ) জোরপূর্বক উন্মুক্তকরণ প্রয়োগ করা, এর মূল মানদণ্ড অবশ্যই সমগ্র সভ্যতার দ্বারা সাধারণত তৈরি করতে হবে</li><li>প্রযুক্তি ন্যায়বিচার মূল্যায়ন প্রক্রিয়া প্রতিষ্ঠা করা, নিয়মিত প্রযুক্তি বিস্তারের ভারসাম্যপূর্ণতা মূল্যায়ন করা, প্রযুক্তিগতভাবে পিছিয়ে থাকা বিমান এবং গোষ্ঠীকে নির্দিষ্ট সহায়তা প্রদান করা</li></ul><h2 id="৬-প্রযুক্তি-উন্মুক্তকরণ-এবং-নিরাপত্তার-ভারসাম্য" tabindex="-1">৬. প্রযুক্তি উন্মুক্তকরণ এবং নিরাপত্তার ভারসাম্য <a class="header-anchor" href="#৬-প্রযুক্তি-উন্মুক্তকরণ-এবং-নিরাপত্তার-ভারসাম্য" aria-label="Permalink to &quot;৬. প্রযুক্তি উন্মুক্তকরণ এবং নিরাপত্তার ভারসাম্য&quot;">​</a></h2><p>প্রযুক্তি উন্মুক্তকরণ এবং প্রযুক্তি নিরাপত্তার মধ্যে সূক্ষ্ম ভারসাম্য প্রয়োজন। সিম্বায়োসিস সভ্যতার পদ্ধতি হল:</p><ul><li>ভিত্তিগত নীতি এবং সাধারণ জ্ঞান সম্পূর্ণরূপে উন্মুক্ত, আরও বেশি মানুষকে প্রযুক্তির সারাংশ বোঝতে দেয়, যার ফলে প্রযুক্তির ঝুঁকি আরও ভালোভাবে চিহ্নিত করা যায়</li><li>উচ্চ-ঝুঁকি অপারেশনের নির্দিষ্ট প্যারামিটার এবং বাস্তবায়নের বিবরণ সীমাবদ্ধভাবে উন্মুক্ত, শুধুমাত্র নিরাপত্তা শর্ত থাকা প্রতিষ্ঠানের জন্য প্রদান করা হয়</li><li>নিষিদ্ধ প্রযুক্তির জ্ঞান কঠোরভাবে গোপন রাখা হয়, কিন্তু &quot;কেন নিষিদ্ধ&quot; নৈতিক বিশ্লেষণ উন্মুক্ত এবং স্বচ্ছ, সমগ্র সভ্যতাকে সীমার অস্তিত্বের অর্থ বোঝায়</li><li>&quot;দায়িত্বশীল প্রযুক্তি প্রচার&quot; নীতি প্রতিষ্ঠা করা, প্রযুক্তি প্রচারকারীদের প্রযুক্তির নিরাপদ ব্যবহারের পদ্ধতি এবং নৈতিক সীমা একই সাথে প্রচার করার বাধ্যবাধকতা আছে</li></ul><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>প্রযুক্তি উন্মুক্তকরণ এবং ভাগাভাগির প্রক্রিয়া হল অ্যাঙ্কর সিম্বায়োসিস সভ্যতাকে লুটের সভ্যতা থেকে আলাদা করে এমন গুরুত্বপূর্ণ বৈশিষ্ট্যগুলির মধ্যে একটি। লুটের ব্যবস্থায়, প্রযুক্তি হল শক্তিশালীদের দুর্বলদের দমন করার সরঞ্জাম; সিম্বায়োসিস সভ্যতায়, প্রযুক্তি হল সব জাতির সম্মিলিত বিবর্তনের সিঁড়ি। শ্রেণীবিভাগ উন্মুক্তকরণ, মৌলিক অবকাঠামো বিস্তার, যুক্তিসঙ্গত উদ্দীপনা এবং একচেটিয়া বিরোধী নিশ্চিতকরণের মাধ্যমে, সিম্বায়োসিস সভ্যতা একটি &quot;জ্ঞান স্বাধীনভাবে প্রবাহিত, ক্ষমতা সাধারণভাবে বৃদ্ধি পায়, অবদান ন্যায়সঙ্গতভাবে প্রতিদান পায়&quot; এমন প্রযুক্তি ইকোসিস্টেম তৈরি করছে, যা সভ্যতার সামগ্রিক মাত্রা উন্নয়নের জন্য ক্রমাগত উদ্ভাবনের শক্তি সরবরাহ করে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>60-প্রযুক্তি ব্যবস্থার সংক্ষিপ্ত বিবরণ</li><li>68-প্রযুক্তিগত নৈতিকতা এবং নিরাপত্তা সীমা</li><li>47-একচেটিয়া বিরোধী আইন</li></ul>',25)])])}const b=a(d,[["render",e]]);export{_ as __pageData,b as default};
